// Claude Messages API (Anthropic format) pass-through.
//
// The upstream accepts the same API keys for both the OpenAI and the
// Claude format, so there is no translation here: /v1/messages requests
// are forwarded to the upstream byte-for-byte and the upstream response
// is returned as-is. Failover, per-key rate limits, request logging and
// the dashboard work exactly like the OpenAI endpoints. Only errors
// generated by the gateway itself are rendered in the Anthropic error
// shape; upstream errors pass through verbatim via proxyErrorBody.
package gateway

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"
)

func writeClaudeError(w http.ResponseWriter, status int, errType, message string) {
	writeJSON(w, status, map[string]any{
		"type":  "error",
		"error": map[string]any{"type": errType, "message": message},
	})
}

func (g *Gateway) claudeAuth(w http.ResponseWriter, r *http.Request) bool {
	if g.cfg.Server.MasterKey == "" {
		return true
	}
	if strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ") == g.cfg.Server.MasterKey {
		return true
	}
	if r.Header.Get("x-api-key") == g.cfg.Server.MasterKey {
		return true
	}
	writeClaudeError(w, http.StatusUnauthorized, "authentication_error", "invalid master key")
	return false
}

func (g *Gateway) claudeMessages(w http.ResponseWriter, r *http.Request) {
	if !g.claudeAuth(w, r) {
		return
	}
	if r.Method != http.MethodPost {
		writeClaudeError(w, http.StatusMethodNotAllowed, "invalid_request_error", "method not allowed")
		return
	}
	body, err := io.ReadAll(io.LimitReader(r.Body, 32<<20))
	if err != nil {
		writeClaudeError(w, http.StatusBadRequest, "invalid_request_error", "cannot read body")
		return
	}
	var meta struct {
		Model  string `json:"model"`
		Stream bool   `json:"stream"`
	}
	if json.Unmarshal(body, &meta) != nil {
		writeClaudeError(w, http.StatusBadRequest, "invalid_request_error", "invalid JSON body")
		return
	}
	lg := &requestLog{modelRequested: meta.Model, modelUpstream: meta.Model, start: time.Now(), stream: meta.Stream}
	res := g.runAttempts(r.Context(), r.Method, "/v1/messages", body, meta.Stream, lg)
	if res.canceled {
		return
	}
	if res.resp != nil {
		lg.keyID = res.key.ID()
		lg.status = res.resp.StatusCode
		if meta.Stream {
			g.serveClaudeStream(w, r, res.resp, lg)
		} else {
			g.serveClaudeJSON(w, res.resp, lg)
		}
		res.key.ReportSuccess()
		res.release()
		res.cancel()
		g.finishLog(lg)
		return
	}
	if res.noKey != nil {
		if res.lastErr != nil {
			if res.lastErr.retryAfter == 0 && res.noKey.RetryAfter > 0 {
				w.Header().Set("Retry-After", fmt.Sprintf("%d", int(res.noKey.RetryAfter.Seconds())))
			}
			proxyErrorBody(w, res.lastErr)
			lg.keyID = ""
			lg.status = res.lastErr.status
			lg.errMsg = strings.TrimSpace(string(res.lastErr.body))
			g.finishLog(lg)
			return
		}
		if res.noKey.RetryAfter > 0 {
			w.Header().Set("Retry-After", fmt.Sprintf("%d", int(res.noKey.RetryAfter.Seconds())))
		}
		writeClaudeError(w, http.StatusTooManyRequests, "rate_limit_error", res.noKey.Error())
		lg.keyID = ""
		lg.status = http.StatusTooManyRequests
		lg.errMsg = res.noKey.Error()
		g.finishLog(lg)
		return
	}
	if res.poolErr != nil {
		writeClaudeError(w, http.StatusServiceUnavailable, "overloaded_error", res.poolErr.Error())
		lg.keyID = ""
		lg.status = http.StatusServiceUnavailable
		lg.errMsg = res.poolErr.Error()
		g.finishLog(lg)
		return
	}
	if res.lastErr != nil {
		proxyErrorBody(w, res.lastErr)
		return
	}
	writeClaudeError(w, http.StatusBadGateway, "api_error", "all upstream keys failed: "+res.lastErrMsg)
}

type claudeUsage struct {
	InputTokens          int `json:"input_tokens"`
	OutputTokens         int `json:"output_tokens"`
	CacheReadInputTokens int `json:"cache_read_input_tokens"`
}

func (g *Gateway) serveClaudeJSON(w http.ResponseWriter, resp *http.Response, lg *requestLog) {
	defer resp.Body.Close()
	b, err := io.ReadAll(io.LimitReader(resp.Body, 64<<20))
	if err != nil {
		writeClaudeError(w, http.StatusBadGateway, "api_error", "cannot read upstream response")
		return
	}
	var parsed struct {
		Usage *claudeUsage `json:"usage"`
	}
	if json.Unmarshal(b, &parsed) == nil && parsed.Usage != nil {
		lg.promptTokens = parsed.Usage.InputTokens
		lg.cachedTokens = parsed.Usage.CacheReadInputTokens
		lg.completionTokens = parsed.Usage.OutputTokens
		lg.totalTokens = parsed.Usage.InputTokens + parsed.Usage.OutputTokens
	}
	for k, vs := range resp.Header {
		if strings.EqualFold(k, "Content-Length") {
			continue
		}
		for _, v := range vs {
			w.Header().Add(k, v)
		}
	}
	w.WriteHeader(resp.StatusCode)
	_, _ = w.Write(b)
}

func (g *Gateway) serveClaudeStream(w http.ResponseWriter, r *http.Request, resp *http.Response, lg *requestLog) {
	defer resp.Body.Close()
	flusher, ok := w.(http.Flusher)
	if !ok {
		writeClaudeError(w, http.StatusInternalServerError, "api_error", "streaming not supported")
		return
	}
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.WriteHeader(resp.StatusCode)
	flusher.Flush()

	scanner := bufio.NewScanner(resp.Body)
	scanner.Buffer(make([]byte, 64*1024), 10*1024*1024)
	for scanner.Scan() {
		line := scanner.Bytes()
		if bytes.HasPrefix(line, []byte("data:")) {
			data := bytes.TrimSpace(line[len("data:"):])
			if len(data) > 0 && !bytes.Equal(data, []byte("[DONE]")) {
				var evt struct {
					Usage   *claudeUsage `json:"usage"`
					Message *struct {
						Usage *claudeUsage `json:"usage"`
					} `json:"message"`
				}
				if json.Unmarshal(data, &evt) == nil {
					u := evt.Usage
					if u == nil && evt.Message != nil {
						u = evt.Message.Usage
					}
					if u != nil {
						if u.InputTokens > 0 {
							lg.promptTokens = u.InputTokens
						}
						if u.CacheReadInputTokens > 0 {
							lg.cachedTokens = u.CacheReadInputTokens
						}
						if u.OutputTokens > 0 {
							lg.completionTokens = u.OutputTokens
						}
						lg.totalTokens = lg.promptTokens + lg.completionTokens
					}
				}
			}
		}
		_, _ = w.Write(line)
		_, _ = w.Write([]byte("\n"))
		flusher.Flush()
		if r.Context().Err() != nil {
			return
		}
	}
}
